import{_ as l,l as i,o as e,c as s,v as r,p,x as o,d as n,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"反向代理","description":"","frontmatter":{"title":"反向代理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reverse-proxy.md","filePath":"cs/reverse-proxy.md","lastUpdated":1789023840000}'),c={name:"cs/reverse-proxy.md"};function T(_,a,S,E,m,P){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="反向代理" tabindex="-1">反向代理 <a class="header-anchor" href="#反向代理" aria-label="Permalink to &quot;反向代理&quot;">​</a></h1><div class="epigraph"><p>客户端只看见代理；代理终止 TLS、补头、缓存、再开到后端的连接。它是 L7 的具体形态，不是又一种路由协议。</p><footer>—— 据 RFC 9110 网关/代理；HTTP 实践整理</footer></div><p><a href="/cs/l4-l7-load-balancing">L7 LB</a> 常以反向代理实现。<a href="/cs/cdn-cache-hierarchy">CDN</a> 边缘也是。<a href="/cs/maglev-lb">上一课</a> 可把流量先送到代理层。缺口是<strong>代理职责</strong>：Hop-by-hop 头、连接复用、缓冲。本课不把服务发现写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浏览器不直连应用进程。反向代理：证书、HTTP/1.1 到后端 H2 的转换、压缩、WAF、限流令牌桶。<code>X-Forwarded-For</code> 传原 IP，信任边界要钉。缓冲：代理若把 SSE 攒满再发，实时死——接 SSE 课。WS 要 Upgrade 透传。</p><p>不要把反向代理写成正向代理（客户端配置出去）。</p><p><span class="marginnote">RFC 9110 定义 proxy/gateway。本课不点名 nginx 配置项当标准。</span></p><h3 id="面向客户的网关" tabindex="-1">面向客户的网关 <a class="header-anchor" href="#面向客户的网关" aria-label="Permalink to &quot;面向客户的网关&quot;">​</a></h3><p>终止 TLS、改头、池化后端。hop-by-hop 头不盲目转发。缓冲会杀 SSE。与正向代理方向相反。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：客户 → 代理（TLS 终）→ 后端池。对照 Maglev 纯 L4：不终结 TLS。与 SSH 反向隧道不同方向。</p>',11)),(e(),p(h,null,{default:o(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLI%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20RP%5B%22%E5%8F%8D%E5%90%91%E4%BB%A3%E7%90%86%22%5D%0A%20%20RP%20--%3E%20TLS%5B%22%E7%BB%88%E6%AD%A2%20TLS%22%5D%0A%20%20RP%20--%3E%20POOL%5B%22%E5%90%8E%E7%AB%AF%E8%BF%9E%E6%8E%A5%E6%B1%A0%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连接池摊销后端握手，像 HTTP 持久。TSO 在代理两侧。健康检查由代理做。Cookie 会话可钉后端。QUIC 在代理终止，后端常 HTTP/1.1。PMTUD 在两段各自发生。</p><p>安全：代理是集中点，配置错误会泄露内网。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入缓存键的全部边角。服务发现是下一课。后课默认：反向代理终结客户协议并转发；hop-by-hop 头不盲目转发。</p><p>把代理超时设太短会拆合法 SSE/WS。</p><p>上一课留下的缺口在本课收口；「反向代理」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/service-discovery">服务发现</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反向代理是面向客户的 L7 网关。</li><li>管 TLS、头、池、缓冲。</li><li>与纯 L4 Maglev 分层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9110；HTTP 网关实践。</li></ul>',10))])}const A=l(c,[["render",T]]);export{u as __pageData,A as default};
